class Solution {
public:
    string maximumBinaryString(string binary) {
        int n = binary.size();
        int firstZero = -1;
        int zeroCount = 0;
        for (int i = 0; i < n; i++) {
            if (binary[i] == '0') {
                if (firstZero == -1) firstZero = i;
                zeroCount++;
            }
        }
        if (zeroCount == 0) return binary;
        int zeroPos = firstZero + zeroCount - 1;
        for (int i = 0; i < n; i++) {
            binary[i] = '1';
        }
        binary[zeroPos] = '0';
        return binary;
    }
};
